    });

    const repositoryList = repositoryItems.length
      ? `<ul>${repositoryItems.join('\n')}</ul>`
      : '<p class="muted">No GitHub repositories were returned for this connected account.</p>';

    res.status(200).type('html').send(
      htmlPage(
        'Dashboard',
        `<main class="card

