      htmlPage(
        'Dashboard',
        `<main class="card">
          <h1>Dashboard</h1>
          <p>Signed in as <strong>${escapeHtml(email)}</strong></p>
          <h2>GitHub repositories for ${escapeHtml(AGENTKIT_IDENTIFIER)}</h2>
