let scalekitClient;
function getScalekitClient() {
  if (!scalekitClient) {
    const { SCALEKIT_ENV_URL, SCALEKIT_CLIENT_ID, SCALEKIT_CLIENT_SECRET } = process.env;
    if (!SCALEKIT_ENV_URL || !SCALEKIT_CLIENT_ID || !SCALEKIT_CLIENT_SECRET) {
      throw new Error(
