  if (!data) {
    return [];
  }

  if (Array.isArray(data)) {
    return data;
  }

  if (Array.isArray(data.array)) {
    return data.array;
  }

  if (Array.isArray(data.repositories)) {
    return data.repositories;
  }

  if (Array.isArray(data.repos)) {
    return data.repos;
  }

  if (Array.isArray(data.items)) {
    return data.items;
  }

  return [];
}

